import android.widget.LinearLayout
import android.widget.TextView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import kotlinx.coroutines.launch

class MainActivity : AppCompatActivity() {

    private lateinit var container: LinearLayout
        private val prefs by lazy { getSharedPreferences("tg_prefs", Context.MODE_PRIVATE) }

            override fun onCreate(savedInstanceState: Bundle?) {
                    super.onCreate(savedInstanceState)
                            container = LinearLayout(this).apply {
                                        orientation = LinearLayout.VERTICAL
                                                    setPadding(48, 48, 48, 48)
                                                            }
                                                                    setContentView(container)

                                                                            val savedId = prefs.getInt("api_id", 0)
                                                                                    val savedHash = prefs.getString("api_hash", "")

                                                                                            if (savedId != 0 && !savedHash.isNullOrEmpty()) {
                                                                                                        TelegramClient.init(applicationContext, savedId, savedHash)
                                                                                                                    observeAuthState()
                                                                                                                            } else {
                                                                                                                                        showApiCredentialsForm()
                                                                                                                                                }
                                                                                                                                                    }

                                                                                                                                                        private fun showApiCredentialsForm() {
                                                                                                                                                                clearScreen()
                                                                                                                                                                        addText("Enter your Telegram API credentials", 18f, isBold = true)
                                                                                                                                                                                addText("Get these from my.telegram.org -> API Development Tools.", 14f)

                                                                                                                                                                                        val idInput = EditText(this).apply { 
                                                                                                                                                                                                    hint = "api_id (numbers only)" 
                                                                                                                                                                                                                setPadding(16, 16, 16, 16)
                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                val hashInput = EditText(this).apply { 
                                                                                                                                                                                                                                            hint = "api_hash" 
                                                                                                                                                                                                                                                        setPadding(16, 16, 16, 16)
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                        container.addView(idInput)
                                                                                                                                                                                                                                                                                container.addView(hashInput)

                                                                                                                                                                                                                                                                                        val saveButton = Button(this).apply { 
                                                                                                                                                                                                                                                                                                    text = "Save & Connect" 
                                                                                                                                                                                                                                                                                                                setPadding(16, 16, 16, 16)
                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                saveButton.setOnClickListener {
                                                                                                                                                                                                                                                                                                                                            val id = idInput.text.toString().trim().toIntOrNull()
                                                                                                                                                                                                                                                                                                                                                        val hash = hashInput.text.toString().trim()
                                                                                                                                                                                                                                                                                                                                                                    if (id == null || hash.isEmpty()) {
                                                                                                                                                                                                                                                                                                                                                                                    Toast.makeText(this, "Enter a valid api_id and api_hash", Toast.LENGTH_SHORT).show()
                                                                                                                                                                                                                                                                                                                                                                                                    return@setOnClickListener
                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                            prefs.edit().putInt("api_id", id).putString("api_hash", hash).apply()
                                                                                                                                                                                                                                                                                                                                                                                                                                        TelegramClient.init(applicationContext, id, hash)
                                                                                                                                                                                                                                                                                                                                                                                                                                                    observeAuthState()
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    container.addView(saveButton)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            private fun observeAuthState() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    lifecycleScope.launch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                TelegramClient.authState.collect { state ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                when (state) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    is AuthState.Idle -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            clearScreen()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    addText("🔄 Starting Telegram client...", 18f, isBold = true)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            addText("Please wait, connecting to Telegram servers...", 14f)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    is AuthState.WaitPhone -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            clearScreen()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    addText("📱 Waiting for Phone Number", 18f, isBold = true)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            showLoginInput("Enter your phone number (e.g., +15551234567)") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        TelegramClient.submitPhone(it)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        is AuthState.WaitCode -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                clearScreen()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        addText("🔑 Waiting for Login Code", 18f, isBold = true)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                addText("Check your Telegram app for the code.", 14f)
